/* Built-in branding images (generated by tools/make_brand.py into brand_data.c). */
#ifndef GBADS_BRAND_H
#define GBADS_BRAND_H

#include <stddef.h>

enum { BRAND_LOGO, BRAND_BTN_A, BRAND_BTN_B, BRAND_NO_SAVES, BRAND_BTN_L1, BRAND_BTN_R1,
       BRAND_FLAG_US, BRAND_FLAG_EU, BRAND_FLAG_JP, BRAND_FLAG_FR, BRAND_FLAG_DE, BRAND_COUNT };

typedef struct {
	const unsigned char* png;
	size_t size;
} BrandImage;

extern const BrandImage brandImages[BRAND_COUNT];

/* Menu text in Futura Bold Italic: white on transparent, brandTextCap * 2 px
 * tall with the capitals centred vertically. */
typedef struct {
	const char* text;
	const unsigned char* png;
	size_t size;
} BrandText;

extern const BrandText brandTexts[];
extern const int brandTextCount;
extern const int brandTextCap;

#endif
